//! The `dataset-digests` subcommand: record and re-check dataset determinism.
//!
//! [`climb_dns::generate_dataset`] promises byte-identical output for a given
//! `(size, seed)`. This command turns that promise into a committed artifact:
//! it hashes the generated bytes under the documented canonical encoding and
//! writes one digest per dataset size. `cargo xtask verify-numbers` recomputes
//! the recorded digests on every validation run.

use anyhow::{bail, Context, Result};
use clap::Args;
use std::fs;
use std::path::PathBuf;

use climb_bench::DEFAULT_WIRE_SEED;
use climb_dns::{DatasetDigestDocument, DatasetSize};

use crate::SizeArg;

/// Arguments for `cargo xtask dataset-digests`.
#[derive(Args)]
pub(crate) struct DatasetDigestsArgs {
    /// Dataset sizes to record (comma-separated). `all` expands to every
    /// predefined size, including the million-message one.
    #[arg(long, value_delimiter = ',', default_value = "small,onek,medium")]
    sizes: Vec<SizeArg>,

    /// Seed for deterministic dataset generation. Defaults to the benchmark
    /// seed so the digests describe the bytes the measurements actually signed.
    #[arg(long, default_value_t = DEFAULT_WIRE_SEED)]
    seed: u64,

    /// Output path for the committed digest document.
    #[arg(long, default_value = "docs/sample-output/dataset-digests.json")]
    out: PathBuf,

    /// Compare the generated document with the one on disk instead of writing.
    #[arg(long)]
    check: bool,
}

/// Generate (or check) the dataset-digest document.
pub(crate) fn cmd_dataset_digests(args: DatasetDigestsArgs) -> Result<()> {
    let sizes = selected_digest_sizes(&args.sizes);
    let document = DatasetDigestDocument::generate(args.seed, &sizes);

    if args.check {
        let text = fs::read_to_string(&args.out)
            .with_context(|| format!("failed to read {}", args.out.display()))?;
        let recorded: DatasetDigestDocument = serde_json::from_str(&text)
            .with_context(|| format!("failed to parse {}", args.out.display()))?;
        if recorded != document {
            bail!(
                "{} is stale; regenerate with `cargo xtask dataset-digests --sizes {}`",
                args.out.display(),
                sizes
                    .iter()
                    .map(|size| size.label().to_lowercase())
                    .collect::<Vec<_>>()
                    .join(",")
            );
        }
        println!(
            "dataset-digests: {} entr{} in {} match",
            document.digests.len(),
            if document.digests.len() == 1 {
                "y"
            } else {
                "ies"
            },
            args.out.display()
        );
        return Ok(());
    }

    if let Some(parent) = args.out.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("failed to create parent dirs for {}", args.out.display()))?;
    }
    let mut json = serde_json::to_string_pretty(&document)
        .context("failed to serialize the digest document")?;
    json.push('\n');
    fs::write(&args.out, json)
        .with_context(|| format!("failed to write {}", args.out.display()))?;

    for entry in &document.digests {
        println!(
            "{:<7} {:>8} messages  {}",
            entry.size, entry.count, entry.digest
        );
    }
    println!("wrote {}", args.out.display());
    Ok(())
}

/// Expand `all` to every predefined size and deduplicate while preserving the
/// requested order.
fn selected_digest_sizes(args: &[SizeArg]) -> Vec<DatasetSize> {
    let mut sizes = Vec::new();
    for arg in args {
        let expanded: Vec<DatasetSize> = match arg {
            SizeArg::All => DatasetSize::all().to_vec(),
            SizeArg::Small => vec![DatasetSize::Small],
            SizeArg::OneK => vec![DatasetSize::OneK],
            SizeArg::Medium => vec![DatasetSize::Medium],
            SizeArg::Large => vec![DatasetSize::Large],
        };
        for size in expanded {
            if !sizes.contains(&size) {
                sizes.push(size);
            }
        }
    }
    sizes
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn all_expands_to_every_size() {
        assert_eq!(
            selected_digest_sizes(&[SizeArg::All]),
            DatasetSize::all().to_vec()
        );
    }

    #[test]
    fn explicit_sizes_dedupe_and_keep_order() {
        assert_eq!(
            selected_digest_sizes(&[SizeArg::Medium, SizeArg::Small, SizeArg::Medium]),
            vec![DatasetSize::Medium, DatasetSize::Small]
        );
    }

    #[test]
    fn all_plus_explicit_adds_nothing_new() {
        assert_eq!(
            selected_digest_sizes(&[SizeArg::All, SizeArg::OneK]),
            DatasetSize::all().to_vec()
        );
    }
}
